"use client";
import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";

const categories = [
  { label: "Fashion & Lifestyle", icon: "👗" },
  { label: "Electronics & Gadgets", icon: "📱" },
  { label: "Home & Living", icon: "🏠" },
  { label: "Beauty & Personal Care", icon: "💄" },
  { label: "Toys, Kids & Baby", icon: "🧸" },
  { label: "Food & Grocery", icon: "🛒" },
  { label: "Sports & Fitness", icon: "🏀" },
  { label: "Automotive Accessories", icon: "🚗" },
  { label: "Gifts & Handcrafts", icon: "🎁" },
  { label: "Books & Stationery", icon: "📚" },
];

export default function CategoriesSlider() {
  const [startIndex, setStartIndex] = useState(0);

  const nextSlide = () => {
    setStartIndex((prev) => (prev + 5) % categories.length);
  };

  const prevSlide = () => {
    setStartIndex((prev) =>
      prev - 5 < 0 ? categories.length - 5 : prev - 5
    );
  };

  useEffect(() => {
    const timer = setInterval(nextSlide, 5000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="w-full mx-auto p-8 text-center bg-black relative">
      <h2 className="text-3xl font-semibold mb-6 text-white tracking-wide">
        Shop by Categories
      </h2>

      <div className="relative overflow-hidden">
        <AnimatePresence mode="wait">
          <motion.div
            key={startIndex}
            initial={{ opacity: 0, x: 100 }}
            animate={{ opacity: 1, x: 0 }}
            exit={{ opacity: 0, x: -100 }}
            transition={{ duration: 0.6 }}
            className="
              grid 
              grid-cols-1
              sm:grid-cols-2
              md:grid-cols-3
              lg:grid-cols-5
              gap-4 select-none
            "
          >
            {categories.slice(startIndex, startIndex + 5).map((item, index) => (
              <motion.div
                key={index}
                whileHover={{ scale: 1.05 }}
                className="bg-white/10 backdrop-blur-md border border-white/20 p-6 rounded-xl 
                           shadow-lg hover:bg-white/20 cursor-pointer transition flex flex-col items-center 
                           text-white"
              >
                <span className="text-4xl mb-2">{item.icon}</span>
                <p className="text-sm font-medium">{item.label}</p>
              </motion.div>
            ))}
          </motion.div>
        </AnimatePresence>

        {/* Prev Button */}
        <button
          onClick={prevSlide}
          className="absolute left-0 top-1/2 -translate-y-1/2 bg-gray-800/60 text-white
                     hover:bg-gray-700 px-4 py-2 rounded-full"
        >
          ‹
        </button>

        {/* Next Button */}
        <button
          onClick={nextSlide}
          className="absolute right-0 top-1/2 -translate-y-1/2 bg-gray-800/60 text-white
                     hover:bg-gray-700 px-4 py-2 rounded-full"
        >
          ›
        </button>
      </div>
    </div>
  );
}
